        'reports' => ['reports.php', 'Reports & trends'],
        'export' => ['exports.php', 'Export summary'],
    ];
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo htmlspecialchars($title); ?> | ProcrastiTrack Admin</title><link rel="stylesheet" href="admin.css?v=20261021"><link rel="stylesheet" href="refined.css?v=20261114-responsive"><link rel="stylesheet" href="workspace.css?v=20261107"><script>try{if(localStorage.getItem('pt-admin-theme')==='dark')document.documentElement.dataset.theme='dark';}catch(e){}</script></head><body><div class="admin-shell"><aside class="admin-sidebar"><div class="brand"><div class="admin-mark">P</div><div><strong>ProcrastiTrack</strong><small>Admin workspace</small></div></div><p class="nav-caption">WORKSPACE</p><nav class="admin-nav" aria-label="Admin navigation"><?php foreach($links as $key => $link): if($key==='users' && !in_array($admin['role'],['admin','superadmin'],true)) continue; ?><a class="<?php echo $key === $active ? 'active' : ''; ?>" href="<?php echo $link[0]; ?>"><span class="nav-symbol" aria-hidden="true"><?php echo ['dashboard'=>'&#9638;','users'=>'&#9678;','reports'=>'&#8599;','export'=>'&#8595;'][$key]; ?></span><?php echo htmlspecialchars($link[1]); ?></a><?php endforeach; ?></nav><div class="sidebar-support"><span aria-hidden="true">&#10022;</span><strong>Support with perspective.</strong><p>Bring student activity into focus. Turn patterns into thoughtful support.</p><a href="reports.php">Explore reports &rarr;</a></div><div class="admin-footer"><strong><?php echo htmlspecialchars($admin['fullname'] ?? 'Administrator'); ?></strong><br><span><?php echo htmlspecialchars(ucfirst($admin['role'] ?? 'admin')); ?> · <a href="logout.php">Sign out</a></span></div></aside><main class="admin-main"><div class="workspace-topline"><span>Workspace / <strong><?php echo htmlspecialchars($title); ?></strong></span><span><?php echo (new DateTimeImmutable("now",new DateTimeZone("Asia/Manila")))->format("D, M j, Y"); ?></span></div> <header class="admin-top"><div><p class="eyebrow">Counselor workspace</p><h1><?php echo htmlspecialchars($title); ?></h1><p>Evidence-led student support with privacy-first reporting.</p></div><div class="admin-user"><button type="button" id="adminThemeToggle" class="button secondary" aria-pressed="false">Dark mode</button> Signed in as <strong><?php echo htmlspecialchars($admin['fullname'] ?? 'Admin'); ?></strong></div></header><?php
}
function admin_page_end() { echo '</main></div><script src="theme.js?v=20261021"></script><script src="../assets/js/auto-dismiss-notices.js?v=20261124"></script></body></html>'; }
function admin_query_value($conn, $sql, $key = 'value') { $result = mysqli_query($conn, $sql); if (!$result) return 0; $row = mysqli_fetch_assoc($result); return $row[$key] ?? 0; }
